/**
 * @react-native-async-storage/async-storage stub — hooks/node_modules/ test double.
 *
 * Same separation guarantee as the expo-notifications stub:
 *   Node.js tests → this file (nearest node_modules/)
 *   Metro builds  → real package (metro.config.js blockList blocks this path)
 */

export const _storage = new Map();
export const _reset   = () => { _storage.clear(); };

const AsyncStorage = {
  getItem:    async (key)        => _storage.get(key) ?? null,
  setItem:    async (key, value) => { _storage.set(key, value); },
  removeItem: async (key)        => { _storage.delete(key); },
  clear:      async ()           => { _storage.clear(); },
  _storage,
  _reset,
};

export default AsyncStorage;
